package vn.codegym;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/products")public class ProductServlet extends HttpServlet{private final ProductDao dao=new ProductDao();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{if("delete".equals(r.getParameter("action")))dao.delete(Integer.parseInt(r.getParameter("id")));r.setAttribute("products",dao.all());r.getRequestDispatcher("/products.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{int id=r.getParameter("id").isBlank()?0:Integer.parseInt(r.getParameter("id"));dao.save(new Product(id,r.getParameter("name"),Double.parseDouble(r.getParameter("price")),Integer.parseInt(r.getParameter("quantity"))));s.sendRedirect("products");}catch(Exception e){throw new ServletException(e);}}}
